"""Compare the actual first-upload PNG and its repair, never first-generation drafts."""
import html
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]/'assets/profile-borders-v1-repaired'
items=json.loads((ROOT/'manifest.json').read_text());cards=[]
for a in items:
    extra=''
    if a['tier']=='legendary' and a.get('layer_manifest'):
        layer=json.loads((ROOT/a['layer_manifest']).read_text())
        files=[('테두리',layer['frame'])]+[(p['name'],p['file']) for p in layer['parts']]
        links=''.join(f'<a href="{p}" download><img src="{p}" loading="lazy" alt="{html.escape(n)}">{html.escape(n)}</a>' for n,p in files)
        extra='<details><summary>전설 개별 PNG 레이어</summary><div class="layers">'+links+'</div></details>'
    active=a.get('animation',a['file'])
    cards.append(f'''<article data-tier="{a['tier']}"><h2>{a['id']:03} · {html.escape(a['name'])}</h2><div class="pair"><section><h3>기준 · 첫 GitHub 업로드 844e7c2</h3><div class="sample"><div class="avatar"></div><img src="{a['reference_file']}" alt="승인 기준 {a['id']:03}" loading="lazy"></div></section><section><h3>V1 디자인 보정본</h3><div class="sample"><div class="avatar"></div><img class="repair" src="{a['file']}" data-poster="{a['file']}" data-active="{active}" alt="V1 보정 {a['id']:03}" loading="lazy"></div></section></div><p>{a['tier']} · {'원본 그대로 보존' if a['status']=='preserved_without_changes' else '기존 구성 유지 · 변형 보정'} · {'전설만 레이어 분리' if a['tier']=='legendary' else '그림 레이어 분리 없음'}</p><a href="{a['file']}" download>보정 PNG</a>{(' · <a href="'+active+'" download>이펙트·동작 SVG</a>') if 'animation' in a else ''}{extra}</article>''')
status='100종 보정' if len(items)==100 else f'{len(items)}종 보정 · 진행 중'
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta name="asset-reference" content="844e7c2"><title>V1 기준 보정 · 844e7c2 비교</title><style>*{box-sizing:border-box}body{margin:0;padding:28px;background:#f0f2f3;color:#243044;font:15px system-ui}header{max-width:1000px;margin-bottom:24px}h1{font-size:28px}h2{font-size:17px}h3{font-size:12px;font-weight:500;color:#5d6e82;min-height:30px}p{line-height:1.7}nav{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}button{border:1px solid #bbc6cd;border-radius:18px;padding:8px 13px;background:white;color:#263447;cursor:pointer}button[aria-pressed=true]{background:#273f56;color:white}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(440px,1fr));gap:22px}article{background:white;border:1px solid #d5dfe4;border-radius:12px;padding:15px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:15px}.sample{position:relative;aspect-ratio:1;background:#dfe5ec;border-radius:8px}.sample>img{position:absolute;inset:0;width:100%;height:100%}.avatar{position:absolute;left:15.0390625%;top:15.0390625%;width:69.921875%;height:69.921875%;background:#9eb0c4;border-radius:50%}article p,a,summary{font-size:13px}a{color:#34677e}summary{cursor:pointer;margin-top:12px}.layers{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.layers a{background:#e7edf0;padding:5px;text-align:center}.layers img{width:100%;height:90px;object-fit:contain;display:block}.dark .sample{background:#172237}.dark .avatar{background:#344b61}.no-avatar .avatar{display:none}.compact .sample{width:128px;height:128px;margin:auto}[hidden]{display:none!important}@media(max-width:500px){body{padding:12px}.grid{grid-template-columns:1fr}.pair{gap:8px}}</style><header><strong>''' + status + '''</strong><h1>첫 GitHub 업로드 디자인을 기준으로 보정</h1><p>왼쪽은 두 번째 수정 후 처음 업로드한 <a href="https://github.com/mangocrab/website-jeon_yong/tree/844e7c2/assets/profile-borders">844e7c2의 PNG</a>, 오른쪽은 그 디자인의 보정본입니다. 첫 생성 이미지나 V2 재디자인을 기준으로 삼지 않았습니다.</p><p>일반·고급·희귀·영웅: 기존 그림을 유지하고 변형만 보정합니다.<br>영웅은 PNG 한 장에 후광·명암 이펙트만 추가하며, 레이어 분리는 전설에만 적용합니다.<br>1024×1024 · 중심 (512, 512) · 안쪽 원 지름 716px · 중앙 완전 투명.</p><nav><button data-filter="all" aria-pressed="true">전체</button><button data-filter="normal">일반</button><button data-filter="premium">고급</button><button data-filter="rare">희귀</button><button data-filter="epic">영웅</button><button data-filter="legendary">전설</button></nav><nav><button id="effects" aria-pressed="false">보정본 이펙트·동작 켜기</button><button id="actual-size" aria-pressed="false">128px로 확인</button><button id="background">배경 밝기 변경</button><button id="avatar">프로필 원 표시 / 숨기기</button></nav></header><main class="grid">'''+''.join(cards)+'''</main><script>document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('article').forEach(a=>a.hidden=b.dataset.filter!=='all'&&a.dataset.tier!==b.dataset.filter)});let effects=false;document.querySelector('#effects').onclick=()=>{effects=!effects;document.querySelectorAll('img.repair').forEach(i=>i.src=effects?i.dataset.active:i.dataset.poster);document.querySelector('#effects').setAttribute('aria-pressed',String(effects));document.querySelector('#effects').textContent=effects?'보정본 정지 PNG로 보기':'보정본 이펙트·동작 켜기'};document.querySelector('#actual-size').onclick=()=>{const on=document.body.classList.toggle('compact');document.querySelector('#actual-size').setAttribute('aria-pressed',String(on))};document.querySelector('#background').onclick=()=>document.body.classList.toggle('dark');document.querySelector('#avatar').onclick=()=>document.body.classList.toggle('no-avatar');</script></html>'''
(ROOT/'index.html').write_text(page)
print('First-upload comparison pairs:',len(items))
